cat > optimize.py <<'PY'
import pickle,numpy as np
from scipy.optimize import minimize
from rdkit import Chem
from rdkit.Chem import AllChem
m,idx,arms=pickle.load(open('molecule.pkl','rb'));org=pickle.load(open('org.pkl','rb'))
ff=AllChem.UFFGetMoleculeForceField(org,ignoreInterfragInteractions=True)
x=m.GetConformer().GetPositions().copy(); n=len(x)
co1=idx['Co1'];co2=idx['Co2'];nc=idx['Nc'];nim=idx['Nim'];nd=idx['Ndist']
dists=[];angs=[]
def ds(a,b,r,k):dists.append((a,b,r,k))
def angle(a,b,c,deg,k):angs.append((a,b,c,np.cos(np.radians(deg)),k))
ds(co1,co2,2.40,450);ds(nc,co1,2.13,450)
for k, (ring,na,ch,p) in enumerate(arms):
 ds(na,co1,1.96,450)
 angle(nc,co1,na,80,120)
 angle(ring[1],na,co1,120,80);angle(ch,na,co1,120,80)
 angle(ring[0],nc,co1,110,90)
 if k in [1,2]:
  ds(p,co2,2.24,450)
  angle(co1,co2,p,97,60)
  for nei in org.GetAtomWithIdx(p).GetNeighbors():angle(nei.GetIdx(),p,co2,112,50)
for k in range(3):
 for j in range(k):angle(arms[k][1],co1,arms[j][1],117,100)
angle(nc,co1,co2,180,160)
ds(co2,nim,1.72,500)
angle(co1,co2,nim,145,90)
angle(arms[1][3],co2,arms[2][3],115,80)
for k in [1,2]:angle(arms[k][3],co2,nim,100,60)
angle(co2,nim,nd,165,80)
ds(nim,nd,1.40,100)
# extra interfragment short-range repulsion
lig=list(range(46))+list(range(58,n))
# use graph fragment membership instead
frags=Chem.GetMolFrags(org)
lig=[f for f in frags if nc in f][0];hyd=[f for f in frags if nim in f][0]
rad={'C':1.65,'N':1.5,'P':1.85,'Si':1.90,'H':1.1,'Co':1.4}
rep=[]
for i in lig:
 for j in hyd:
  r=0.83*(rad[m.GetAtomWithIdx(i).GetSymbol()]+rad[m.GetAtomWithIdx(j).GetSymbol()])
  rep.append((i,j,r))
for co in [co1,co2]:
 bound={a.GetIdx() for a in m.GetAtomWithIdx(co).GetNeighbors()}
 near=set(bound)
 for a in bound:near.update(c.GetIdx() for c in m.GetAtomWithIdx(a).GetNeighbors())
 for i in list(lig)+list(hyd):
  if i not in near:rep.append((co,i,0.85*(1.25+rad[m.GetAtomWithIdx(i).GetSymbol()])))
ri=np.array([i for i,j,r in rep]);rj=np.array([j for i,j,r in rep]);rr=np.array([r for i,j,r in rep])
def evaluate(y,scale=1.):
 xx=y.reshape(n,3)
 e=ff.CalcEnergy(y.tolist());g=np.array(ff.CalcGrad(y.tolist())).reshape(n,3)
 for i,j,r,k in dists:
  vec=xx[i]-xx[j];dd=np.linalg.norm(vec);diff=dd-r
  e+=scale*k*diff*diff
  gg=scale*2*k*diff*vec/max(dd,1e-10);g[i]+=gg;g[j]-=gg
 for i,j,k,c0,w in angs:
  u=xx[i]-xx[j];v=xx[k]-xx[j];du=np.linalg.norm(u);dv=np.linalg.norm(v);a=u/du;b=v/dv;c=a@b;dc=c-c0
  e+=scale*w*dc*dc
  gi=scale*2*w*dc*(b-c*a)/du;gk=scale*2*w*dc*(a-c*b)/dv
  g[i]+=gi;g[k]+=gk;g[j]-=gi+gk
 v=xx[ri]-xx[rj];d=np.linalg.norm(v,axis=1);dr=np.minimum(d-rr,0);w=70
 e+=w*(dr**2).sum();gr=2*w*(dr/np.maximum(d,1e-10))[:,None]*v
 np.add.at(g,ri,gr);np.add.at(g,rj,-gr)
 return e,g.ravel()
for scale,it in [(0.4,1800),(1,2500),(2,2500)]:
 res=minimize(lambda y:evaluate(y,scale),x.ravel(),method='L-BFGS-B',jac=True,options={'maxiter':it,'gtol':0.01,'ftol':1e-10,'maxls':40})
 x=res.x.reshape(n,3);print(scale,res.success,res.fun,res.message,flush=True)
np.save('optimized.npy',x)
for i,j,r,k in dists:print(m.GetAtomWithIdx(i).GetSymbol(),i,m.GetAtomWithIdx(j).GetSymbol(),j,round(np.linalg.norm(x[i]-x[j]),3),'target',r)
for i,j,k,c0,w in angs: 
 a=x[i]-x[j];b=x[k]-x[j];print(i,j,k,round(np.degrees(np.arccos(np.clip(a@b/np.linalg.norm(a)/np.linalg.norm(b),-1,1))),1),'target',round(np.degrees(np.arccos(c0)),1))
with open('answer.xyz','w') as f:
 f.write(f'{n}\nDinuclear cobalt complex; Cartesian coordinates in angstroms\n')
 for atom,pos in zip(m.GetAtoms(),x-x[[co1,co2]].mean(axis=0)):
  f.write(f'{atom.GetSymbol():2s} {pos[0]: .8f} {pos[1]: .8f} {pos[2]: .8f}\n')
PY
OPENBLAS_NUM_THREADS=1 python optimize.py
